templates.template:
/* =============================================================================
   MAC — a XenForo 2.3 port of the MyBB "MAC" theme.
   A Mac OS X style galaxy wallpaper behind a frosted grey glass panel, the embossed
   "MAC" title, silver tabs, grey gradient title bars and pale grey post rows.
   The galaxy is drawn with CSS gradients and one small star image, so no uploads.
   ============================================================================= */

// Change this to your board's name, or delete the "Title" section to use a logo image.
@mac-title: "MAC";

@mac-bar: linear-gradient(180deg, #cbc8cc 0%, #bdbdbd 40%, #b3b3b3 70%, #a8abaa 100%);
@mac-tab: linear-gradient(180deg, #dcdbdd 0%, #c8c8c8 50%, #b8b8b8 100%);
@mac-sub: #d8dbda;

// ---- Galaxy wallpaper ------------------------------------------------------------------

html
{
	background-color: #2a1245;
	background-image:
		url("data:image/png;base64,"),
		radial-gradient(ellipse 30% 35% at 82% 38%, rgba(240, 105, 215, .95) 0%, rgba(240, 105, 215, 0) 100%),
		radial-gradient(ellipse 45% 30% at 55% 50%, rgba(255, 225, 248, .55) 0%, rgba(255, 225, 248, 0) 100%),
		radial-gradient(ellipse 35% 45% at 18% 70%, rgba(130, 85, 175, .85) 0%, rgba(130, 85, 175, 0) 100%),
		radial-gradient(ellipse 40% 30% at 70% 85%, rgba(125, 95, 170, .8) 0%, rgba(125, 95, 170, 0) 100%),
		linear-gradient(180deg, #000 0%, #0b0925 8%, #361b4d 22%, #5a2c80 45%, #714b9a 65%, #6a3784 85%, #1a0835 100%);
	background-repeat: repeat, no-repeat, no-repeat, no-repeat, no-repeat, no-repeat;
	background-attachment: fixed;
	background-size: 400px 400px, cover, cover, cover, cover, cover;
}

body
{
	background: transparent;
}

// ---- The frosted glass panel ---------------------------------------------------------

.p-pageWrapper
{
	max-width: 1154px;
	margin: 8px auto 0;
	background: rgba(196, 192, 200, .62);
	border-radius: 8px 8px 0 0;
	-webkit-backdrop-filter: blur(2px);
	backdrop-filter: blur(2px);
}

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner,
.p-footer-inner
{
	max-width: 1114px;
}

.p-header,
.p-nav,
.p-sectionLinks,
.p-body,
.p-footer
{
	background: transparent;
	border: none;
}

// ---- Title ------------------------------------------------------------------------------

.p-header
{
	background: linear-gradient(180deg, rgba(140, 140, 140, .9) 0, rgba(150, 150, 150, .75) 55px, rgba(150, 150, 150, 0) 100%);
	border-radius: 8px 8px 0 0;
}

.p-header-content
{
	justify-content: center;
	padding: 18px 0 4px;
}

.p-header-logo
{
	margin: 0 auto;

	img
	{
		display: none;
	}

	a
	{
		text-decoration: none;

		&::after
		{
			content: @mac-title;
			font-family: 'Arial Black', 'Helvetica Neue', Arial, sans-serif;
			font-size: 64px;
			font-weight: 900;
			line-height: 1;
			letter-spacing: 1px;
			color: #9a9a9a;
			text-shadow: -1px -1px 0 #e6e6e6, 1px 2px 0 #5a5a5a, 2px 4px 6px rgba(0, 0, 0, .55);
		}
	}
}

// ---- Silver tabs ---------------------------------------------------------------------------

.p-navSticky.is-sticky .p-nav
{
	background: rgba(196, 192, 200, .92);
}

.p-nav-list
{
	justify-content: center;
	width: 100%;
	gap: 8px;

	.p-navEl
	{
		background: @mac-tab;
		border-radius: 6px 6px 0 0;
		box-shadow: inset 0 1px 0 rgba(255, 255, 255, .7);
	}

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		color: #222;
		font-weight: 700;
		font-size: 13px;
		text-shadow: 0 1px 0 rgba(255, 255, 255, .6);

		&:hover
		{
			color: #000;
			text-decoration: none;
		}
	}

	.p-navEl.is-selected
	{
		background: linear-gradient(180deg, #f0f0f0 0%, #d8d8d8 100%);
	}
}

.p-nav .p-navgroup
{
	background: transparent;
}

.p-nav .p-navgroup-link,
.p-nav-menuTrigger,
.p-nav-smallLogo
{
	color: #222;

	&:hover
	{
		background: rgba(255, 255, 255, .35);
		color: #000;
		text-decoration: none;
	}
}

// Sub-navigation: the grey "welcome back" box
.p-sectionLinks-inner
{
	background: linear-gradient(180deg, #c4c1c4 0%, #b6b6b6 55%, #a7a6a7 100%);
	border: 1px solid rgba(255, 255, 255, .5);
	border-radius: 4px;
	color: #222;

	a
	{
		color: #6a6a6a;

		&:hover
		{
			color: #222;
		}
	}
}

// ---- Body ------------------------------------------------------------------------------

.p-body-inner
{
	color: #222;
	padding-top: 10px;
}

.p-breadcrumbs
{
	font-weight: 700;

	a
	{
		color: #7a7a7a;

		&:hover
		{
			color: #333;
		}
	}

	> li:last-child a
	{
		display: inline-block;
		padding: 2px 6px;
		background: #c2c3c0;
		border-radius: 4px;
		color: #222;
	}
}

.p-title-value
{
	color: #222;
	text-shadow: 0 1px 0 rgba(255, 255, 255, .5);
}

// ---- Blocks: grey gradient title bars, pale grey rows ---------------------------------------

.block-container
{
	background: #f6f6f6;
	border: 1px solid rgba(255, 255, 255, .55);
	border-radius: 4px;
	box-shadow: 0 1px 3px rgba(40, 20, 60, .25);
}

.block-header,
.block-filterBar,
.menu-header,
.overlay-title
{
	background: @mac-bar;
	border-bottom: 1px solid #a3a3a3;
	color: #fff;
	font-weight: 700;
	text-shadow: 0 1px 2px rgba(0, 0, 0, .5);

	a,
	a:hover
	{
		color: #fff;
	}

	.block-desc
	{
		color: rgba(255, 255, 255, .85);
	}
}

.block-minorHeader,
.block-tabHeader,
.menu-tabHeader,
.dataList-row--header .dataList-cell
{
	background: @mac-sub;
	border-bottom: 1px solid #c4c6c5;
	color: #222;
	font-weight: 700;
	text-shadow: none;

	a
	{
		color: #222;
	}
}

.block-tabHeader .tabs-tab,
.menu-tabHeader .tabs-tab
{
	color: #6a6a6a;

	&:hover
	{
		color: #222;
	}

	&.is-active
	{
		color: #222;
		border-color: #8a8a8a;
	}
}

.block-footer
{
	background: @mac-bar;
	border-top-color: #a3a3a3;
	color: #fff;

	a
	{
		color: #fff;
	}
}

.node + .node,
.structItem
{
	border-top-color: #dedede;
}

.node-body,
.structItem
{
	background: #f6f6f6;
}

.node-title a,
.structItem-title a
{
	color: #333;
	font-weight: 700;

	&:hover
	{
		color: #000;
	}
}

.node-icon i
{
	color: #8a8a8a;
}

.node--unread .node-icon i
{
	color: #5a5a5a;
}

.message,
.message-inner
{
	background: #f6f6f6;
	border-color: #d4d4d4;
}

.message-cell--user
{
	background: #efefef;
	border-right-color: #d4d4d4;
}

.message-attribution
{
	background: @mac-sub;
	color: #222;
}

// ---- Buttons: small silver pills ----------------------------------------------------------

.button,
a.button
{
	background: linear-gradient(180deg, #f2f2f2 0%, #d6d6d6 100%);
	border: 1px solid #9a9a9a;
	color: #222;

	&:hover
	{
		background: linear-gradient(180deg, #fafafa 0%, #e2e2e2 100%);
		color: #000;
	}
}

.button.button--primary,
a.button.button--primary
{
	background: @mac-bar;
	border-color: #8a8a8a;
	color: #fff;
	text-shadow: 0 1px 2px rgba(0, 0, 0, .5);
}

// ---- Footer: the grey links bar ----------------------------------------------------------

.p-footer-inner
{
	padding-bottom: 14px;
	color: #222;
}

.p-footer-row
{
	background: linear-gradient(180deg, #d4d4d4 0%, #c4c4c4 100%);
	border: 1px solid rgba(255, 255, 255, .55);
	border-radius: 4px;
	padding: 4px 10px;

	a
	{
		color: #7a7a7a;

		&:hover
		{
			color: #222;
		}
	}
}

.p-footer-copyright
{
	color: #222;

	a
	{
		color: #7a7a7a;
	}
}

@media (max-width: 1174px)
{
	.p-pageWrapper
	{
		margin-top: 0;
		border-radius: 0;
	}
}
